/** The page an issue is served at, or the workspace root if it cannot be resolved. */
async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return "/";
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return `/${org.slug}`;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return `/${org.slug}`;
  return issuePath(org.slug, project.slug, issue.number);
}

async function notifyAssigned(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId,
  actorId: UserId | null,
): Promise<void> {
  await notify(orgId, "issue_assigned", [assigneeId], {
    title: "You were assigned an issue",
    body: `Issue ${issueId} is now yours`,
    href: await issueHref(orgId, issueId),
    actorId,
  });
}

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notifyAssigned(
      payload.orgId,
      payload.issueId,
      payload.assigneeId,
      payload.actorId,
    );
  });

  // Being assigned at creation is an assignment like any other.
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await notifyAssigned(
      payload.orgId,
      payload.issueId,
      payload.assigneeId,
      payload.actorId,
    );
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;

    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue changed status",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];
    const href = await issueHref(payload.orgId, payload.issueId);

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is told about the newcomer; the newcomer is not told about
  // themselves (`notify` drops the recipient who is also the actor).
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.userId,
    });
  });

  // A refused write tells the owner, whoever tried. While the previous alert
  // for the same resource is still unread, further refusals add nothing.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = await orgRepo.findOrgById(payload.orgId);
    if (!org) return;

    const title = `Plan limit reached: ${payload.resource}`;
    const pending = await notificationRepo.countUnreadMatching(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      title,
    );
    if (pending > 0) return;

    await notify(payload.orgId, "plan_limit_reached", [org.ownerId], {
      title,
      body: `${org.name} is using ${payload.used} of ${payload.limit} ${payload.resource} on the ${org.plan} plan`,
      href: settingsPath(org.slug, "billing"),
      actorId: null,
    });
  });
}

registerFanOut();
