      return project ? projectPath(orgSlug, project.slug) : fallback;
    }
    case "issue":
      return issueHrefFor(orgId, orgSlug, subjectId as Issue["id"], fallback);
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      return comment
        ? issueHrefFor(orgId, orgSlug, comment.issueId, fallback)
        : fallback;
    }
  }
}

async function issueHrefFor(
  orgId: OrgId,
  orgSlug: string,
  issueId: Issue["id"],
  fallback: string,
): Promise<string> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return fallback;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project ? issuePath(orgSlug, project.slug, issue.number) : fallback;
}

